import type { Note } from '../../../schema/note'

/**
 * An interaction record from GET /InteractionRecords ("Query account
 * interaction records."), https://developers.ploomes.com/json/openapi.json.
 * Documented fields read here:
 *
 *   Id         "Interaction record Id, automatically generated by the Database."
 *   ContactId  "Interaction record contact Id."            (required)
 *   DealId     "Interaction record deal id."                (optional)
 *   Content    "Interaction record content."                (required)
 *
 * `Date` ("Interaction record date. If it is empty, it receives the current
 * creation date.") is the record's own date, not its creation time, so it is
 * left in metadata rather than passed off as created_at.
 */
export interface RawPloomesNote {
  Id: number
  ContactId?: number | null
  DealId?: number | null
  Date?: string
  TypeId?: number
  Title?: string | null
  Content?: string | null
  [key: string]: unknown
}

export function transformNote(raw: RawPloomesNote): Note {
  if (typeof raw.Content !== 'string') {
    throw new Error(`Ploomes interaction record ${raw.Id} has no Content`)
  }
  return {
    id: String(raw.Id),
    content: raw.Content,
    contact_id: raw.ContactId != null ? String(raw.ContactId) : undefined,
    deal_id: raw.DealId != null ? String(raw.DealId) : undefined,
    metadata: raw,
  }
}

export function untransformNote(data: Partial<Note>): Record<string, unknown> {
  const out: Record<string, unknown> = {}
  if (data.content !== undefined) out.Content = data.content
  if (data.contact_id !== undefined) out.ContactId = Number(data.contact_id)
  if (data.company_id !== undefined) out.AccountId = Number(data.company_id)
  if (data.deal_id !== undefined) out.DealId = Number(data.deal_id)
  if (data.owner_id !== undefined) out.OwnerId = Number(data.owner_id)
  return out
}
